head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 3. 샘플파일(spinne_SKT-689_(WSQ-2168)_timeSec.xml)을 실행 후 하단의 3번째 spinner에 시분초(100000)를 입력한다.
    //3. Run the sample file (spinne_SKT-689_ (WSQ-2168) _timeSec.xml) and enter the time in seconds (100000) in the third spinner at the bottom.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_11___input').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_11___input').setValue('100000')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_11___input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 10:00:00이 입력되어 진다.
    //3. 10:00:00 is entered.
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_11___input').realValue == '10:00:00'", "true");
    //WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. spinner의 증감버튼을 클릭한다.
    //4. Click the Increase button on the spinner.
    //Verify 4. 1초씩 증감되어진다.
    //4. Increase or decrease by 1 second.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_11_upButton').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_11___input').realValue == '10:00:01'", "true");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 26-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
